@startuml

class Client {
  + Nin
  + Tin
  + Name
  + Address
}

class BicycleModel {
  + Name
  + Type
  + No_Gears
}

class Bicycle {
  + Number
}

class Store {
  + Name
  + Address
}

class Reservation {
  + Pickup_Day
  + Return_Day
}

class Rental {
  + Return_Date
}

Client "1" -- "*" Reservation : makes
Reservation "*" -- "1" BicycleModel : for
Reservation "*" -- "1" Store : at
Reservation "0..1" -- "1" Rental : results in
Rental "1" -- "1" Bicycle : uses

@enduml

